arguments:
{"script":"rm -rf logs
mkdir -p logs
for i in $(seq 0 6); do
  d=$(date -d "$i days ago" +%F 2>/dev/null || date -v -${i}d +%F)
  file=logs/log_${d}.txt
  :> "$file"
  for j in $(seq 1 100); do
    r=$((RANDOM%6))
    case $r in
      0) echo "Error: failed to process item $j" >>"$file";;
      1) echo "error occurred at step $j" >>"$file";;
      2) echo "INFO: step $j completed" >>"$file";;
      3) echo "Warning: possible issue $j" >>"$file";;
      4) echo "debug: value $j" >>"$file";;
      5) echo "Note: error-handling tested for $j" >>"$file";;
    esac
  done
done
grep -rio "error" logs | wc -l
"}

